package io.aetheris.orchestrator.notification;import io.aetheris.orchestrator.approval.ApprovalService;import org.springframework.stereotype.Service;@Service public class NotificationDeliveryService {private final NotificationService notifications;private final ApprovalService approvals;public NotificationDeliveryService(NotificationService notifications,ApprovalService approvals){this.notifications=notifications;this.approvals=approvals;}public NotificationDeliveryResult deliver(NotificationDeliveryRequest r){NotificationEntity n=notifications.required(r.notificationId());NotificationChannel channel=r.channel()==null?NotificationChannel.IN_APP:r.channel();if(channel==NotificationChannel.IN_APP)return new NotificationDeliveryResult(channel,true,"DELIVERED",n.getTitle());if(r.taskId()==null||!approvals.hasApproved(r.taskId(),"NOTIFICATION_DELIVERY_"+channel.name()))return new NotificationDeliveryResult(channel,false,"APPROVAL_REQUIRED","External notification delivery requires exact owner approval for this task/channel.");return new NotificationDeliveryResult(channel,false,"ADAPTER_NOT_CONNECTED","The "+channel+" delivery contract exists, but no external provider is connected in Stage 8.");}}
